import unittest
from candidate import largest_divisor

class TestLargestDivisor(unittest.TestCase):
    def test_largest_divisor_normal_case(self):
        self.assertEqual(largest_divisor(15), 5)

    def test_largest_divisor_even_number(self):
        self.assertEqual(largest_divisor(10), 5)

    def test_largest_divisor_prime_number(self):
        self.assertEqual(largest_divisor(7), 1)

    def test_largest_divisor_smallest_positive(self):
        self.assertEqual(largest_divisor(2), 1)

    def test_largest_divisor_large_number(self):
        self.assertEqual(largest_divisor(100), 50)

    def test_largest_divisor_square_number(self):
        self.assertEqual(largest_divisor(36), 18)

    def test_largest_divisor_with_zero(self):
        with self.assertRaises(ZeroDivisionError):
            largest_divisor(0)

    def test_largest_divisor_negative_number(self):
        self.assertEqual(largest_divisor(-15), 5)

    def test_largest_divisor_negative_prime(self):
        self.assertEqual(largest_divisor(-7), 1)

    def test_largest_divisor_none_input(self):
        with self.assertRaises(TypeError):
            largest_divisor(None)

    def test_largest_divisor_non_integer_input(self):
        with self.assertRaises(TypeError):
            largest_divisor("15")

    def test_largest_divisor_floating_point_input(self):
        with self.assertRaises(TypeError):
            largest_divisor(15.5)

    def test_largest_divisor_edge_case_minus_one(self):
        self.assertEqual(largest_divisor(-1), 1)

    def test_largest_divisor_edge_case_minus_two(self):
        self.assertEqual(largest_divisor(-2), 1)

    def test_largest_divisor_edge_case_minus_three(self):
        self.assertEqual(largest_divisor(-3), 1)

    def test_largest_divisor_large_prime(self):
        self.assertEqual(largest_divisor(999983), 1)

    def test_largest_divisor_large_composite(self):
        self.assertEqual(largest_divisor(1000000), 500000)

if __name__ == '__main__':
    unittest.main()
